const sessionId = typeof $json.sessionId === 'string' ? $json.sessionId.trim() : '';
const requestId = typeof $json.requestId === 'string' ? $json.requestId.trim() : '';
const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const error = (uuidPattern.test(sessionId) && uuidPattern.test(requestId))
  ? null
  : { code: 'INVALID_SESSION', message: 'Checking the Gmail connection needs a valid conversation and request ID.' };
return [{ json: {
  valid: error === null, sessionId, requestId,
  proposedInput: { sessionId, requestId },
  ...(error ? { response: { ok: false, error } } : {}),
} }];

const raw = $input.first().json ?? {};
const status = Number(raw.statusCode ?? 0);
const body = raw.body ?? {};
// When no credential is selected at all, n8n fails the node rather than
// returning a status, and onError passes the item through with `error` set.
const nodeError = String(raw.error?.message ?? raw.error ?? '');

const CONNECT_STEPS = [
  'Open n8n at http://localhost:5678',
  'Go to Credentials and open the one named "Gmail (read-only)". If it is not there yet, create it: Create credential, choose Google OAuth2 API, and name it exactly Gmail (read-only).',
  'Select Connect my account. Google opens its own sign-in and permission window.',
  'Grant access. The permission screen should say the app wants to view your email. If it mentions sending or deleting, the Scope field is wrong.',
].join(' | ');

let state = 'unknown';
let message = '';

if (status === 200 && body.emailAddress) {
  state = 'connected';
  message = `Gmail is connected as ${body.emailAddress}.`;
} else if (status === 401 || status === 403 || /insufficient|unauthor/i.test(String(body?.error?.message ?? ''))) {
  state = 'needs_reauth';
  message = 'Gmail is set up but Google is refusing the connection. It usually needs reconnecting: this happens about a week after setup if the Google consent screen is still in Testing rather than published.';
} else if (!status || /credential/i.test(nodeError)) {
  state = 'not_connected';
  message = 'There is no working Gmail connection yet. It has to be created once in n8n; it cannot be done from this chat.';
} else {
  state = 'unknown';
  message = `Gmail did not answer as expected (${status || 'no response'}). It may be a temporary network problem.`;
}

return [{ json: {
  connected: state === 'connected',
  state,
  message,
  emailAddress: state === 'connected' ? String(body.emailAddress) : '',
  messagesTotal: state === 'connected' ? Number(body.messagesTotal ?? 0) : 0,
  credentialUrl: 'http://localhost:5678/home/credentials',
  connectSteps: CONNECT_STEPS,
  scope: 'https://www.googleapis.com/auth/gmail.readonly',
  // The chat turns this one exact address into a button. Any other wording,
  // including a markdown link, renders as plain text and the learner has
  // nothing to click.
  linkInstruction: 'Include the exact text http://localhost:5678/home/credentials in your reply. The chat turns it into a button that opens the credential screen. Do not rewrite it, wrap it in markdown, or describe it instead.',
} }];

const input = $('Validate Connection Input').first().json;
const probe = $input.first().json;

const NEXT = {
  connected: 'Tell the user which mailbox it is connected to. Nothing more is needed.',
  not_connected: 'Include the exact text http://localhost:5678/home/credentials in your reply so the chat shows a button straight to the credential screen. Then tell them, briefly: open the one named Gmail (read-only), select Connect my account, and grant access when Google asks. Say the permission screen should mention viewing email and nothing about sending or deleting. When they come back to this tab the update carries on by itself, so they do not need to report back. If they say they have already connected it, do not send them back to Google: this same check also fails when the credential exists but the workflows were imported before it did. Tell them to run import-workflows.command once (import-workflows-windows.cmd on Windows) and publish the main agent again, which is written up in docs/MONTHLY_UPDATE.md under the heading about Gmail reading as not connected straight after they connected it.',
  needs_reauth: 'The connection has lapsed. Include the exact text http://localhost:5678/home/credentials so they can reopen the credential and select Connect my account again. If this is about a week after they set it up, add that publishing the Google consent screen stops it expiring every seven days.',
  unknown: 'Say it could not be checked right now and offer to try again. Do not tell the user to reconfigure anything on the strength of one failed check.',
};

return [{ json: { ...input, response: {
  ok: true,
  connected: probe.connected,
  state: probe.state,
  emailAddress: probe.emailAddress,
  mailboxSize: probe.messagesTotal,
  credentialUrl: probe.credentialUrl,
  connectSteps: probe.connectSteps,
  linkInstruction: probe.linkInstruction,
  requiredScope: probe.scope,
  message: probe.message,
  nextStep: NEXT[probe.state] ?? NEXT.unknown,
} } }];

const input = $('Validate Connection Input').first().json;
const response = $json.response ?? { ok: false, error: { code: 'TOOL_FAILED', message: 'The tool did not return a result.' } };
return { json: {
  occurredAt: new Date().toISOString(),
  sessionId: input.sessionId,
  requestId: input.requestId,
  toolName: 'check_gmail_connection',
  proposedInput: JSON.stringify(input.proposedInput ?? {}),
  result: JSON.stringify(response),
  error: response.ok === false ? String(response.error?.message ?? 'Tool failed') : '',
  response
} };

const prepared = $('Prepare Audit').item.json;
const response = { ...prepared.response };
if (!Number.isInteger($json.id)) {
  response.auditWarning = 'The tool result could not be written to the local audit table.';
}
return { json: response };
